import csv

with open('outputs/t11_city_indicator_matrix.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    header = next(reader)
    data = list(reader)

print('Header:', header)
print('Number of rows:', len(data))
print('Number of columns:', len(header))

indicator_cols = [header[i] for i in range(3, len(header))]
print('Indicator columns:', indicator_cols)

missing_counts = {col: 0 for col in indicator_cols}
total_rows = len(data)

for row in data:
    if len(row) != len(header):
        continue
    for i, col in enumerate(indicator_cols):
        if i >= len(row):
            missing_counts[col] += 1
        elif row[i] == '':
            missing_counts[col] += 1

for col in indicator_cols:
    rate = missing_counts[col] / total_rows
    print(f'{col}: missing_count={missing_counts[col]}, missing_rate={rate:.6f}')
""}

