import csv

with open('outputs/t11_city_indicator_matrix.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    header = next(reader)
    data = list(reader)

print('Header:', header)
print('Index mapping:')
for i, col in enumerate(header):
    print(f'  {i}: {col}')

# Count missing for each indicator column
missing_counts = {col: 0 for col in header[3:]}
for row in data:
    if len(row) != len(header):
        continue
    for i in range(3, len(header)):
        if row[i] == '':
            missing_counts[header[i]] += 1

for col in missing_counts:
    rate = missing_counts[col] / len(data)
    print(f'{col}: missing_count={missing_counts[col]}, missing_rate={rate:.6f}')
""}

